.stage-backdrop-image { position: absolute; inset: 0px; width: 100%; height: 100%; object-fit: cover; filter: blur(28px) saturate(1.2); transform: scale(1.15); animation: 500ms ease-out 0s 1 normal both running stage-backdrop-in; }
.stage-backdrop-shade { position: absolute; inset: 0px; background: rgba(0, 0, 0, 0.62); }
.stage-backdrop-dots { z-index: 0; --tri-dot-alpha: 0.2; }
@keyframes stage-backdrop-in {0% { opacity: 0; }}
@media (prefers-reduced-motion: reduce) {.stage-backdrop-image { animation: auto ease 0s 1 normal none running none; }}
.stage-live-label { display: inline-flex; align-items: center; gap: 8px; height: var(--tri-field-h); padding-inline: 9px; color: var(--tri-ink-muted); font-size: var(--tri-control-size); font-weight: 500; line-height: 1; }
.stage-live-signal { display: grid; place-items: center; width: 16px; height: 16px; border: 1px solid rgba(229, 243, 242, 0.16); border-radius: 50%; }
.stage-live-signal > span { width: 6px; height: 6px; border-radius: 50%; background: rgba(229, 243, 242, 0.35); }
@keyframes stage-on-air {0%, 100% { opacity: 1; }
50% { opacity: 0.45; }}
.operator-rail-divider button { display: grid; place-items: center; color: var(--tri-ink-muted); }
.operator-rail .operator-rail-handle, .stage-resizer .stage-resizer-button { width: 28px; height: 12px; border: 0px; background: rgb(22, 25, 24); }
.operator-rail .operator-rail-handle > svg, .stage-resizer .stage-resizer-button > svg { display: block; }
@keyframes tri-ring {0% { stroke-dashoffset: 37.6991; }
100% { stroke-dashoffset: 0; }}
@keyframes tri-chip-in {0% { opacity: 0; transform: scale(0.72); }
100% { opacity: 1; transform: scale(1); }}
@media (prefers-reduced-motion: reduce) {@keyframes tri-chip-in {0% { opacity: 0; transform: none; }
100% { opacity: 1; transform: none; }}}
@keyframes tri-log-rise {0% { transform: translateY(var(--tri-log-row)); }
100% { transform: none; }}
@keyframes tri-log-arrive {0% { opacity: 0; }
100% { opacity: 1; }}
@keyframes tri-tx-fade {0% { opacity: 0; }}
@keyframes tri-tx-rise {0% { opacity: 0; transform: translateY(0.22em); }}
@keyframes tri-tx-blur {0% { opacity: 0; filter: blur(0.2em); }}
@keyframes tri-tx-zoom {0% { opacity: 0; transform: scale(0.92); }}
@keyframes tri-tx-fade {0% { opacity: 0; }}
@keyframes tri-tx-rise {0% { opacity: 0; transform: translateY(0.22em); }}
@keyframes tri-tx-blur {0% { opacity: 0; filter: blur(0.2em); }}
@keyframes tri-tx-zoom {0% { opacity: 0; transform: scale(0.92); }}
.tri-strip-rise { display: grid; grid-template-rows: 0fr; margin-top: 0px; opacity: 0; visibility: hidden; transition: grid-template-rows 340ms var(--tri-ease-out, ease-out), margin-top 340ms var(--tri-ease-out, ease-out),
                    opacity 220ms ease-out, visibility 0s 340ms; }
.tri-strip-rise > div { display: flex; min-height: 0px; min-width: 0px; overflow: hidden; align-items: stretch; }
@keyframes tri-strip-unclip {0% { overflow: hidden; }
100% { overflow: visible; }}
@media (prefers-reduced-motion: reduce) {.tri-strip-rise, .tri-strip-rise[data-open] { transition: opacity 150ms linear; }}
